    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA1RD_1RB1LA_1RB0RB B0_1RB1LC_0LA1RD_1RB1LA_1RB0RB B1_1RB1LC_0LA1RD_1RB1LA_1RB0RB 4 21 p j' [] []).
    + exact run_ovf_1RB1LC_0LA1RD_1RB1LA_1RB0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LA1RD_1RB1LA_1RB0RB p j' E).
    + exact (geo_1RB1LC_0LA1RD_1RB1LA_1RB0RB p j' E).
    + lia.
