  - destruct (lapi_1RB1LC_0LA1RD_1RB1LC_1LC0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA1RD_1RB1LC_1LC0RB B0_1RB1LC_0LA1RD_1RB1LC_1LC0RB B1_1RB1LC_0LA1RD_1RB1LC_1LC0RB 4 19 p j' [] []).
    + exact run_ovf_1RB1LC_0LA1RD_1RB1LC_1LC0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LA1RD_1RB1LC_1LC0RB p j' E).
    + exact (geo_1RB1LC_0LA1RD_1RB1LC_1LC0RB p j' E).
    + lia.
Qed.

