Lemma lbl_1RB1LC_0LA1RD_1RD1LA____0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LC_0LA1RD_1RD1LA____0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_0LA1RD_1RD1LA____0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LC_0LA1RD_1RD1LA____0RB
             = (StA, (rep [S1;S0] (S j) ++ [S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1LC_0LA1RD_1RD1LA____0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
