  { unfold Cc_1RB1LC_0LA1RD_1RD1LA____0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1LC_0LA1RD_1RD1LA____0RB. reflexivity.
