    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA____1RD0LC_0RD0RB B0_1RB1LC_0LA____1RD0LC_0RD0RB B1_1RB1LC_0LA____1RD0LC_0RD0RB 2 8 p j' [] []).
    + exact run_ovf_1RB1LC_0LA____1RD0LC_0RD0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LA____1RD0LC_0RD0RB p j' E).
    + exact (geo_1RB1LC_0LA____1RD0LC_0RD0RB p j' E).
    + lia.
