    apply (lap_of_run tm Cc true true cho_1RB1LC_0LC0RA_1RA0LD_0RB1LC B0_1RB1LC_0LC0RA_1RA0LD_0RB1LC B1_1RB1LC_0LC0RA_1RA0LD_0RB1LC 4 12 p j' [] []).
