Lemma geo_1RB1LC_0LC0RB_1LA0RD_1LC1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_0LC0RB_1LA0RD_1LC1RC) = lift (Cc (Pos.succ p)).
