(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LC_0LC0RB_1LA1LD_0RA___ : sconf := mkC StB (mkS [] [S0;S0] 1 0 [S0;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LC_0LC0RB_1LA1LD_0RA___ : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1LC_0LC0RB_1LA1LD_0RA___ : srun tm true true chb_1RB1LC_0LC0RB_1LA1LD_0RA___ B0_1RB1LC_0LC0RB_1LA1LD_0RA___ = Some (BB1_1RB1LC_0LC0RB_1LA1LD_0RA___, 4, 4).
