(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LC_0LC0RB_1LA1LD_0RA___ : sconf := mkC StB (mkS [] [S0;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LC_0LC0RB_1LA1LD_0RA___ : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 8; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

