(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A0_1RB1LC_0LC0RB_1LA1LD_0RA___.
Proof.
  intros p j q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LC_0LC0RB_1LA1LD_0RA___, cden, A0_1RB1LC_0LC0RB_1LA1LD_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A1_1RB1LC_0LC0RB_1LA1LD_0RA___ = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LC_0LC0RB_1LA1LD_0RA___, cden, A1_1RB1LC_0LC0RB_1LA1LD_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB1LC_0LC0RB_1LA1LD_0RA___ p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LC_0LC0RB_1LA1LD_0RA___ A0_1RB1LC_0LC0RB_1LA1LD_0RA___ A1_1RB1LC_0LC0RB_1LA1LD_0RA___ 4 4
             run_int_1RB1LC_0LC0RB_1LA1LD_0RA___ (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LC_0LC0RB_1LA1LD_0RA___ p j q0 E).
Qed.

Lemma gso_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LC_0LC0RB_1LA1LD_0RA___.
Proof.
  intros p j E. destruct (Alph_00_01_0.cview_none_Alph_00_01_0 p j E) as (H1 & _).
  unfold Cc_1RB1LC_0LC0RB_1LA1LD_0RA___, cden, B0_1RB1LC_0LC0RB_1LA1LD_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_0LC0RB_1LA1LD_0RA___) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_01_0.cview_none_Alph_00_01_0 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LC_0LC0RB_1LA1LD_0RA___
             = (StB, (rep [S0;S0] (S j) ++ [S0;S0;S1], S0, []))).
  { unfold cden, B1_1RB1LC_0LC0RB_1LA1LD_0RA___, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0] (S j) ++ [S0;S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LC_0LC0RB_1LA1LD_0RA___. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LC_0LC0RB_1LA1LD_0RA___. reflexivity.
Qed.

Lemma gsn_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI0_1RB1LC_0LC0RB_1LA1LD_0RA___.
Proof.
  intros v i q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 v i q0 E) as (H1 & _).
  unfold Cin_1RB1LC_0LC0RB_1LA1LD_0RA___, cden, AI0_1RB1LC_0LC0RB_1LA1LD_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB1LC_0LC0RB_1LA1LD_0RA___) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 v i q0 E) as (_ & H2).
  unfold Cin_1RB1LC_0LC0RB_1LA1LD_0RA___, cden, AI1_1RB1LC_0LC0RB_1LA1LD_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB1LC_0LC0RB_1LA1LD_0RA___).
  split; [lia|]. split; [| exact (gen_1RB1LC_0LC0RB_1LA1LD_0RA___ v i q0 E)].
  rewrite (gsn_1RB1LC_0LC0RB_1LA1LD_0RA___ v i q0 E).
  exact (srun_sound tm false true chn_1RB1LC_0LC0RB_1LA1LD_0RA___ AI0_1RB1LC_0LC0RB_1LA1LD_0RA___ AI1_1RB1LC_0LC0RB_1LA1LD_0RA___ 4 4
           run_inner_1RB1LC_0LC0RB_1LA1LD_0RA___ (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall j, lift (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1LD_0RA___) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LC_0LC0RB_1LA1LD_0RA___ = (StB, ((rep [S0;S0] j ++ [S0;S1;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB1LC_0LC0RB_1LA1LD_0RA___, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S0;S0] j ++ [S0;S1;S1], S0, []))).
  { unfold Cin_1RB1LC_0LC0RB_1LA1LD_0RA___. rewrite epow2_1RB1LC_0LC0RB_1LA1LD_0RA___.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LC_0LC0RB_1LA1LD_0RA___. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LC_0LC0RB_1LA1LD_0RA___.
Proof.
  intro j.
  destruct (Alph_00_01_0.cview_none_Alph_00_01_0 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LC_0LC0RB_1LA1LD_0RA___, cden, BE0_1RB1LC_0LC0RB_1LA1LD_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LC_0LC0RB_1LA1LD_0RA___ p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1LD_0RA___ p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1LD_0RA___).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC0RB_1LA1LD_0RA___ j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1LD_0RA___ p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1LD_0RA___ B0_1RB1LC_0LC0RB_1LA1LD_0RA___ BB1_1RB1LC_0LC0RB_1LA1LD_0RA___ 4 4
             run_boot_1RB1LC_0LC0RB_1LA1LD_0RA___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 12), (cden [] [] j B1_1RB1LC_0LC0RB_1LA1LD_0RA___).
    split; [| exact (geo_1RB1LC_0LC0RB_1LA1LD_0RA___ p j E)].
    rewrite (gxi_1RB1LC_0LC0RB_1LA1LD_0RA___ j).
    exact (srun_sound tm true true che_1RB1LC_0LC0RB_1LA1LD_0RA___ BE0_1RB1LC_0LC0RB_1LA1LD_0RA___ B1_1RB1LC_0LC0RB_1LA1LD_0RA___ 4 12
             run_exit_1RB1LC_0LC0RB_1LA1LD_0RA___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LC_0LC0RB_1LA1LD_0RA___ = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1LD_0RA___ q p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1LD_0RA___). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1LD_0RA___ j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1LD_0RA___ p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1LD_0RA___ B0_1RB1LC_0LC0RB_1LA1LD_0RA___ BB1_1RB1LC_0LC0RB_1LA1LD_0RA___ 4 4
             run_boot_1RB1LC_0LC0RB_1LA1LD_0RA___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LC0RB_1LA1LD_0RA___ xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LC_0LC0RB_1LA1LD_0RA___ j)].
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_0LC0RB_1LA1LD_0RA___ p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_0LC0RB_1LA1LD_0RA___ p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LC0RB_1LA1LD_0RA___ : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC0RB_1LA1LD_0RA___ = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LC0RB_1LA1LD_0RA___ p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LC0RB_1LA1LD_0RA___ p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LC_0LC0RB_1LA1LD_0RA___ : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC0RB_1LA1LD_0RA___ = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1LD_0RA___ t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1LD_0RA___). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1LD_0RA___ j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1LD_0RA___ p j E).
