(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LC_0LC0RB_1LA1LD_1RC0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC0RB_1LA1LD_1RC0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1LD_1RC0RA t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1LD_1RC0RA). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1LD_1RC0RA j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1LD_1RC0RA p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1LD_1RC0RA B0_1RB1LC_0LC0RB_1LA1LD_1RC0RA BB1_1RB1LC_0LC0RB_1LA1LD_1RC0RA 4 4
             run_boot_1RB1LC_0LC0RB_1LA1LD_1RC0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LC0RB_1LA1LD_1RC0RA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LC_0LC0RB_1LA1LD_1RC0RA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LC0RB_1LA1LD_1RC0RA : forall t, ~ In t pins_1RB1LC_0LC0RB_1LA1LD_1RC0RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LC0RB_1LA1LD_1RC0RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LC_0LC0RB_1LA1LD_1RC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1LD_1RC0RA (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1LD_1RC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LC0RB_1LA1LD_1RC0RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LC0RB_1LA1LD_1RC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_0LC0RB_1LA1LD_1RC0RA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1LD_1RC0RA (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1LD_1RC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1LD_1RC0RA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1LD_1RC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1LD_1RC0RA (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1LD_1RC0RA [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LC_0LC0RB_1LA1LD_1RC0RA : NeverQuasiHaltsTr tm_1RB1LC_0LC0RB_1LA1LD_1RC0RA.
Proof.
  apply (glue_neverqhtr tm_1RB1LC_0LC0RB_1LA1LD_1RC0RA pins_1RB1LC_0LC0RB_1LA1LD_1RC0RA Cc 1).
  - exact boot_1RB1LC_0LC0RB_1LA1LD_1RC0RA.
