  split; [lia|]. split; [| exact (gen_1RB1LC_0LC0RB_1LA1RD_0LA0RC v i q0 E)].
  rewrite (gsn_1RB1LC_0LC0RB_1LA1RD_0LA0RC v i q0 E).
  exact (srun_sound tm false true chn_1RB1LC_0LC0RB_1LA1RD_0LA0RC AI0_1RB1LC_0LC0RB_1LA1RD_0LA0RC AI1_1RB1LC_0LC0RB_1LA1RD_0LA0RC 4 4
           run_inner_1RB1LC_0LC0RB_1LA1RD_0LA0RC (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
