(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall j, lift (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC = (StB, ((rep [S0;S0] j ++ [S0;S1;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S0;S0] j ++ [S0;S1;S1], S0, []))).
  { unfold Cin_1RB1LC_0LC0RB_1LA1RD_0LA0RC. rewrite epow2_1RB1LC_0LC0RB_1LA1RD_0LA0RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LC_0LC0RB_1LA1RD_0LA0RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC.
Proof.
  intro j.
  destruct (Alph_00_01_0.cview_none_Alph_00_01_0 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LC_0LC0RB_1LA1RD_0LA0RC, cden, BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1RD_0LA0RC p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC0RB_1LA1RD_0LA0RC j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1RD_0LA0RC B0_1RB1LC_0LC0RB_1LA1RD_0LA0RC BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC 4 4
             run_boot_1RB1LC_0LC0RB_1LA1RD_0LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 16), (cden [] [] j B1_1RB1LC_0LC0RB_1LA1RD_0LA0RC).
    split; [| exact (geo_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j E)].
    rewrite (gxi_1RB1LC_0LC0RB_1LA1RD_0LA0RC j).
    exact (srun_sound tm true true che_1RB1LC_0LC0RB_1LA1RD_0LA0RC BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC B1_1RB1LC_0LC0RB_1LA1RD_0LA0RC 8 16
             run_exit_1RB1LC_0LC0RB_1LA1RD_0LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1RD_0LA0RC q p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1RD_0LA0RC j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1RD_0LA0RC B0_1RB1LC_0LC0RB_1LA1RD_0LA0RC BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC 4 4
             run_boot_1RB1LC_0LC0RB_1LA1RD_0LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LC_0LC0RB_1LA1RD_0LA0RC j)].
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LC0RB_1LA1RD_0LA0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LC0RB_1LA1RD_0LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LC0RB_1LA1RD_0LA0RC t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC). split;
      [| exact (gbo_1RB1LC_0LC0RB_1LA1RD_0LA0RC j)].
    rewrite (gso_1RB1LC_0LC0RB_1LA1RD_0LA0RC p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LA1RD_0LA0RC B0_1RB1LC_0LC0RB_1LA1RD_0LA0RC BB1_1RB1LC_0LC0RB_1LA1RD_0LA0RC 4 4
             run_boot_1RB1LC_0LC0RB_1LA1RD_0LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LC0RB_1LA1RD_0LA0RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LC_0LC0RB_1LA1RD_0LA0RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LC0RB_1LA1RD_0LA0RC : forall t, ~ In t pins_1RB1LC_0LC0RB_1LA1RD_0LA0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LC0RB_1LA1RD_0LA0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LC_0LC0RB_1LA1RD_0LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1RD_0LA0RC (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1RD_0LA0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LC0RB_1LA1RD_0LA0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LC0RB_1LA1RD_0LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_0LC0RB_1LA1RD_0LA0RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1RD_0LA0RC (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1RD_0LA0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1RD_0LA0RC (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1RD_0LA0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LC0RB_1LA1RD_0LA0RC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LC0RB_1LA1RD_0LA0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LC_0LC0RB_1LA1RD_0LA0RC : NeverQuasiHaltsTr tm_1RB1LC_0LC0RB_1LA1RD_0LA0RC.
Proof.
  apply (glue_neverqhtr tm_1RB1LC_0LC0RB_1LA1RD_0LA0RC pins_1RB1LC_0LC0RB_1LA1RD_0LA0RC Cc 1).
