    { exists (6 * j + 17), (cden [] [] j BB1_1RB1LC_0LC0RB_1LD0RD_1LA0RA).
      split; [lia|]. split; [| exact (gbo_1RB1LC_0LC0RB_1LD0RD_1LA0RA j)].
