               run_boot_1RB1LC_0LC0RB_1LD0RD_1LA0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LC0RB_1LD0RD_1LA0RA p (pow2 j) (pow2 j));
