      exact (srun_sound tm true true chm_1RB1LC_0LC0RB_1LD0RD_1LA0RA BM0_1RB1LC_0LC0RB_1LD0RD_1LA0RA BM1_1RB1LC_0LC0RB_1LD0RD_1LA0RA 6 6
