Lemma firex_1RB1LC_0LC0RB_1LD1LA_1LA0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LC0RB_1LD1LA_1LA0RA = Some t ->
