      [exact HB1|].
    exists (6 * j + 6), (cden [] [] j BM1_1RB1LC_0LC0RB_1LD1LA_1LA0RA).
    split; [| exact (gbo2_1RB1LC_0LC0RB_1LD1LA_1LA0RA j)].
