(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LC_0LC0RB_1LD1LA_1LA1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A0_1RB1LC_0LC0RB_1LD1LA_1LA1LD.
Proof.
  intros p j q0 E. destruct (Alph_000_001_1.cview_some_Alph_000_001_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LC_0LC0RB_1LD1LA_1LA1LD, cden, A0_1RB1LC_0LC0RB_1LD1LA_1LA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S1;S0] where the anchor has [S1;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LC_0LC0RB_1LD1LA_1LA1LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A1_1RB1LC_0LC0RB_1LD1LA_1LA1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_000_001_1.cview_some_Alph_000_001_1 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LC_0LC0RB_1LD1LA_1LA1LD, cden, A1_1RB1LC_0LC0RB_1LD1LA_1LA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S1;S0]) with (([S1;S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LC_0LC0RB_1LD1LA_1LA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 18), (cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A1_1RB1LC_0LC0RB_1LD1LA_1LA1LD).
  split; [lia|]. split; [| exact (gei_1RB1LC_0LC0RB_1LD1LA_1LA1LD p j q0 E)].
  rewrite (gsi_1RB1LC_0LC0RB_1LD1LA_1LA1LD p j q0 E).
  exact (srun_sound tm false true chi_1RB1LC_0LC0RB_1LD1LA_1LA1LD A0_1RB1LC_0LC0RB_1LD1LA_1LA1LD A1_1RB1LC_0LC0RB_1LD1LA_1LA1LD 6 18
           run_int_1RB1LC_0LC0RB_1LD1LA_1LA1LD (Ap_Alph_000_001_1 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

