Lemma gen_1RB1LC_0LC0RB_1LD1LA_1LA1RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_000_001_00 q0 ++ [S1;S0;S1]) [] i AI1_1RB1LC_0LC0RB_1LD1LA_1LA1RC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_000_001_00.cview_some_Alph_000_001_00 v i q0 E) as (_ & H2).
  unfold Cin_1RB1LC_0LC0RB_1LD1LA_1LA1RC, cden, AI1_1RB1LC_0LC0RB_1LD1LA_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
