Lemma lapin_1RB1LC_0LC0RB_1LD1LA_1LA1RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 6), (cden (Ap_Alph_000_001_00 q0 ++ [S1;S0;S1]) [] i AI1_1RB1LC_0LC0RB_1LD1LA_1LA1RC).
  split; [lia|]. split; [| exact (gen_1RB1LC_0LC0RB_1LD1LA_1LA1RC v i q0 E)].
  rewrite (gsn_1RB1LC_0LC0RB_1LD1LA_1LA1RC v i q0 E).
  exact (srun_sound tm false true chn_1RB1LC_0LC0RB_1LD1LA_1LA1RC AI0_1RB1LC_0LC0RB_1LD1LA_1LA1RC AI1_1RB1LC_0LC0RB_1LD1LA_1LA1RC 6 6
           run_inner_1RB1LC_0LC0RB_1LD1LA_1LA1RC (Ap_Alph_000_001_00 q0 ++ [S1;S0;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
