      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 4]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LC_0LC0RB_1LD1LA_1RA0RA
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 2]).
    vm_compute; reflexivity.
