  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_0LC0RB_1LD1LA_1RA1LC p (pow2 j)).
  - exists (8 * j + 8), (cden [] [] j BB1_1RB1LC_0LC0RB_1LD1LA_1RA1LC).
