(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo3_1RB1LC_0LC0RB_1LD1LA_1RA1LD : forall j, lift (cden [] [] j BM31_1RB1LC_0LC0RB_1LD1LA_1RA1LD) = lift (Cin3 (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BM31_1RB1LC_0LC0RB_1LD1LA_1RA1LD = (StB, (rep [S0;S0;S0] j ++ [S0;S0;S1;S0;S1], S0, []))).
  { unfold cden, BM31_1RB1LC_0LC0RB_1LD1LA_1RA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin3 (pow2 j) = (StB, (rep [S0;S0;S0] j ++ [S0;S0;S1;S0;S1], S0, []))).
  { unfold Cin3_1RB1LC_0LC0RB_1LD1LA_1RA1LD. rewrite epow23_1RB1LC_0LC0RB_1LD1LA_1RA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LC_0LC0RB_1LD1LA_1RA1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi3_1RB1LC_0LC0RB_1LD1LA_1RA1LD : forall j, Cin3 (fill (pow2 j)) = cden [] [] j BE0_1RB1LC_0LC0RB_1LD1LA_1RA1LD.
Proof.
  intro j.
  destruct (Alph_000_001_00.cview_none_Alph_000_001_00 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin3_1RB1LC_0LC0RB_1LD1LA_1RA1LD, cden, BE0_1RB1LC_0LC0RB_1LD1LA_1RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

