Lemma lapi_1RB1LC_0LC0RB_1LD1LA_1RA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (8 * j + 8). split; [lia|].
  rewrite (gsi_1RB1LC_0LC0RB_1LD1LA_1RA1RC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LC_0LC0RB_1LD1LA_1RA1RC A0_1RB1LC_0LC0RB_1LD1LA_1RA1RC A1_1RB1LC_0LC0RB_1LD1LA_1RA1RC 8 8
             run_int_1RB1LC_0LC0RB_1LD1LA_1RA1RC (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LC_0LC0RB_1LD1LA_1RA1RC p j q0 E).
Qed.

Lemma gso_1RB1LC_0LC0RB_1LD1LA_1RA1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LC_0LC0RB_1LD1LA_1RA1RC.
Proof.
  intros p j E. destruct (Alph_000_001_00.cview_none_Alph_000_001_00 p j E) as (H1 & _).
  unfold Cc_1RB1LC_0LC0RB_1LD1LA_1RA1RC, cden, B0_1RB1LC_0LC0RB_1LD1LA_1RA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
