    split; [lia|]. split; [| exact (gbo_1RB1LC_0LC0RB_1LD1RC_1LA1LD j)].
    rewrite (gso_1RB1LC_0LC0RB_1LD1RC_1LA1LD p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LC0RB_1LD1RC_1LA1LD B0_1RB1LC_0LC0RB_1LD1RC_1LA1LD BB1_1RB1LC_0LC0RB_1LD1RC_1LA1LD 6 6
             run_boot_1RB1LC_0LC0RB_1LD1RC_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (12 * j + 21), (cden [] [] j B1_1RB1LC_0LC0RB_1LD1RC_1LA1LD).
    split; [| exact (geo_1RB1LC_0LC0RB_1LD1RC_1LA1LD p j E)].
    rewrite (gxi_1RB1LC_0LC0RB_1LD1RC_1LA1LD j).
    exact (srun_sound tm true true che_1RB1LC_0LC0RB_1LD1RC_1LA1LD BE0_1RB1LC_0LC0RB_1LD1RC_1LA1LD B1_1RB1LC_0LC0RB_1LD1RC_1LA1LD 12 21
             run_exit_1RB1LC_0LC0RB_1LD1RC_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
